with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'البرمجة وعلوم البيانات وتطبيقات الذكاء الاصطناعي في الأرصاد','Python وتحليل البيانات الزمنية والشبكية وواجهات البيانات والأتمتة وضبط الجودة والتعلم الآلي والذكاء الاصطناعي المسؤول.',39,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'البرمجة وتحليل البيانات الجوية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التعلم الآلي والتطبيقات الذكية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('python-meteorological-data-foundations','أساسيات Python للبيانات الأرصادية','الأنواع والهياكل والملفات والتعامل مع السلاسل الزمنية.','{"blocks":[{"type":"text","text":"يعرض الدرس أساسيات Python للبيانات الأرصادية بوصفه مهارة داعمة لتحليل البيانات الجوية أو بناء تطبيقات تنبؤية قابلة للتقييم."},{"type":"text","text":"الفكرة المحورية: الأنواع والهياكل والملفات والتعامل مع السلاسل الزمنية.، مع ربط الطريقة بسؤال أرصادي محدد ومصدر بيانات موثق."},{"type":"text","text":"تبدأ التجربة بتحديد المتغير المستهدف ومجموعة الميزات والوحدات والفترة الزمنية والمقياس المكاني."},{"type":"text","text":"تجرى فحوص جودة للبيانات وتوثق القيم المفقودة والانحرافات ومصادر التحيز المحتملة."},{"type":"text","text":"تقسم البيانات زمنياً أو مكانياً بما يمنع تسرب المعلومات من المستقبل إلى مجموعة التدريب."},{"type":"text","text":"تختار الطريقة أو الخوارزمية وفق طبيعة المسألة وحجم البيانات وقابلية التفسير ومتطلبات التشغيل."},{"type":"text","text":"تستخدم خطوط أساس بسيطة للمقارنة قبل اعتماد نموذج أكثر تعقيداً."},{"type":"text","text":"تقيم النتائج بمقاييس مناسبة للمسألة، مع تحليل الأداء حسب الموسم والمنطقة وشدة الظاهرة."},{"type":"text","text":"تراجع قابلية التعميم عند تغير المناخ أو الأجهزة أو مصادر البيانات أو توزيع المتغيرات."},{"type":"text","text":"توثق الشيفرة والإصدارات والمعلمات ومصدر البيانات وخطوات المعالجة لضمان إعادة الإنتاج."},{"type":"text","text":"مثال تطبيقي: مقارنة نموذج تعلم آلي بخط أساس مناخي أو عددي على فترة اختبار مستقلة لم تستخدم في التدريب."},{"type":"callout","text":"الخلاصة: لا تصبح الأداة مفيدة تشغيلياً إلا بعد تحقق مستقل ومراقبة مستمرة وإشراف علمي بشري."}]}',4160,60,'["تحديد المسألة والبيانات المناسبة","بناء معالجة أو نموذج قابل للتكرار","تقييم الأداء والتحقق من التعميم"]','البرمجة وتحليل البيانات الجوية'),
('python-pandas-weather-timeseries','تحليل السلاسل الزمنية الجوية باستخدام Pandas','تنظيف البيانات وإعادة التشكيل والتجميع الزمني.','{"blocks":[{"type":"text","text":"يعرض الدرس تحليل السلاسل الزمنية الجوية باستخدام Pandas بوصفه مهارة داعمة لتحليل البيانات الجوية أو بناء تطبيقات تنبؤية قابلة للتقييم."},{"type":"text","text":"الفكرة المحورية: تنظيف البيانات وإعادة التشكيل والتجميع الزمني.، مع ربط الطريقة بسؤال أرصادي محدد ومصدر بيانات موثق."},{"type":"text","text":"تبدأ التجربة بتحديد المتغير المستهدف ومجموعة الميزات والوحدات والفترة الزمنية والمقياس المكاني."},{"type":"text","text":"تجرى فحوص جودة للبيانات وتوثق القيم المفقودة والانحرافات ومصادر التحيز المحتملة."},{"type":"text","text":"تقسم البيانات زمنياً أو مكانياً بما يمنع تسرب المعلومات من المستقبل إلى مجموعة التدريب."},{"type":"text","text":"تختار الطريقة أو الخوارزمية وفق طبيعة المسألة وحجم البيانات وقابلية التفسير ومتطلبات التشغيل."},{"type":"text","text":"تستخدم خطوط أساس بسيطة للمقارنة قبل اعتماد نموذج أكثر تعقيداً."},{"type":"text","text":"تقيم النتائج بمقاييس مناسبة للمسألة، مع تحليل الأداء حسب الموسم والمنطقة وشدة الظاهرة."},{"type":"text","text":"تراجع قابلية التعميم عند تغير المناخ أو الأجهزة أو مصادر البيانات أو توزيع المتغيرات."},{"type":"text","text":"توثق الشيفرة والإصدارات والمعلمات ومصدر البيانات وخطوات المعالجة لضمان إعادة الإنتاج."},{"type":"text","text":"مثال تطبيقي: مقارنة نموذج تعلم آلي بخط أساس مناخي أو عددي على فترة اختبار مستقلة لم تستخدم في التدريب."},{"type":"callout","text":"الخلاصة: لا تصبح الأداة مفيدة تشغيلياً إلا بعد تحقق مستقل ومراقبة مستمرة وإشراف علمي بشري."}]}',4170,60,'["تحديد المسألة والبيانات المناسبة","بناء معالجة أو نموذج قابل للتكرار","تقييم الأداء والتحقق من التعميم"]','البرمجة وتحليل البيانات الجوية'),
