('python-weather-api-ingestion','جلب البيانات الجوية من واجهات API','الطلبات والصفحات والتوقيت والتحقق من الاستجابة.','{"blocks":[{"type":"text","text":"يعرض الدرس جلب البيانات الجوية من واجهات API بوصفه مهارة داعمة لتحليل البيانات الجوية أو بناء تطبيقات تنبؤية قابلة للتقييم."},{"type":"text","text":"الفكرة المحورية: الطلبات والصفحات والتوقيت والتحقق من الاستجابة.، مع ربط الطريقة بسؤال أرصادي محدد ومصدر بيانات موثق."},{"type":"text","text":"تبدأ التجربة بتحديد المتغير المستهدف ومجموعة الميزات والوحدات والفترة الزمنية والمقياس المكاني."},{"type":"text","text":"تجرى فحوص جودة للبيانات وتوثق القيم المفقودة والانحرافات ومصادر التحيز المحتملة."},{"type":"text","text":"تقسم البيانات زمنياً أو مكانياً بما يمنع تسرب المعلومات من المستقبل إلى مجموعة التدريب."},{"type":"text","text":"تختار الطريقة أو الخوارزمية وفق طبيعة المسألة وحجم البيانات وقابلية التفسير ومتطلبات التشغيل."},{"type":"text","text":"تستخدم خطوط أساس بسيطة للمقارنة قبل اعتماد نموذج أكثر تعقيداً."},{"type":"text","text":"تقيم النتائج بمقاييس مناسبة للمسألة، مع تحليل الأداء حسب الموسم والمنطقة وشدة الظاهرة."},{"type":"text","text":"تراجع قابلية التعميم عند تغير المناخ أو الأجهزة أو مصادر البيانات أو توزيع المتغيرات."},{"type":"text","text":"توثق الشيفرة والإصدارات والمعلمات ومصدر البيانات وخطوات المعالجة لضمان إعادة الإنتاج."},{"type":"text","text":"مثال تطبيقي: مقارنة نموذج تعلم آلي بخط أساس مناخي أو عددي على فترة اختبار مستقلة لم تستخدم في التدريب."},{"type":"callout","text":"الخلاصة: لا تصبح الأداة مفيدة تشغيلياً إلا بعد تحقق مستقل ومراقبة مستمرة وإشراف علمي بشري."}]}',4210,60,'["تحديد المسألة والبيانات المناسبة","بناء معالجة أو نموذج قابل للتكرار","تقييم الأداء والتحقق من التعميم"]','البرمجة وتحليل البيانات الجوية'),
('python-automated-weather-reports','أتمتة التقارير والنشرات الجوية','إنشاء جداول ورسوم وملخصات دورية.','{"blocks":[{"type":"text","text":"يعرض الدرس أتمتة التقارير والنشرات الجوية بوصفه مهارة داعمة لتحليل البيانات الجوية أو بناء تطبيقات تنبؤية قابلة للتقييم."},{"type":"text","text":"الفكرة المحورية: إنشاء جداول ورسوم وملخصات دورية.، مع ربط الطريقة بسؤال أرصادي محدد ومصدر بيانات موثق."},{"type":"text","text":"تبدأ التجربة بتحديد المتغير المستهدف ومجموعة الميزات والوحدات والفترة الزمنية والمقياس المكاني."},{"type":"text","text":"تجرى فحوص جودة للبيانات وتوثق القيم المفقودة والانحرافات ومصادر التحيز المحتملة."},{"type":"text","text":"تقسم البيانات زمنياً أو مكانياً بما يمنع تسرب المعلومات من المستقبل إلى مجموعة التدريب."},{"type":"text","text":"تختار الطريقة أو الخوارزمية وفق طبيعة المسألة وحجم البيانات وقابلية التفسير ومتطلبات التشغيل."},{"type":"text","text":"تستخدم خطوط أساس بسيطة للمقارنة قبل اعتماد نموذج أكثر تعقيداً."},{"type":"text","text":"تقيم النتائج بمقاييس مناسبة للمسألة، مع تحليل الأداء حسب الموسم والمنطقة وشدة الظاهرة."},{"type":"text","text":"تراجع قابلية التعميم عند تغير المناخ أو الأجهزة أو مصادر البيانات أو توزيع المتغيرات."},{"type":"text","text":"توثق الشيفرة والإصدارات والمعلمات ومصدر البيانات وخطوات المعالجة لضمان إعادة الإنتاج."},{"type":"text","text":"مثال تطبيقي: مقارنة نموذج تعلم آلي بخط أساس مناخي أو عددي على فترة اختبار مستقلة لم تستخدم في التدريب."},{"type":"callout","text":"الخلاصة: لا تصبح الأداة مفيدة تشغيلياً إلا بعد تحقق مستقل ومراقبة مستمرة وإشراف علمي بشري."}]}',4220,60,'["تحديد المسألة والبيانات المناسبة","بناء معالجة أو نموذج قابل للتكرار","تقييم الأداء والتحقق من التعميم"]','البرمجة وتحليل البيانات الجوية'),
